//! Verified no-merge relocation, serialized with native document I/O.
use std::{fs,io::Read,path::{Path,PathBuf},sync::Mutex};
use serde_json::{json,Value};
pub static IO:Mutex<()>=Mutex::new(());
static MOVES:Mutex<Vec<(PathBuf,PathBuf)>>=Mutex::new(Vec::new());
fn portable(path:&Path)->String{let p=path.to_string_lossy().replace('\\',"/");let p=if let Some(rest)=p.strip_prefix("//?/UNC/"){format!("//{rest}")}else{p.strip_prefix("//?/").unwrap_or(&p).to_owned()};p.trim_end_matches('/').to_owned()}
fn move_suffix(path:&Path,root:&Path)->Option<PathBuf>{
 if let Ok(rel)=path.strip_prefix(root){return Some(rel.to_path_buf());}
 if let (Ok(actual),Ok(base))=(path.canonicalize(),root.canonicalize()){if let Ok(rel)=actual.strip_prefix(base){return Some(rel.to_path_buf());}}
 let a=portable(path);let b=portable(root);let win=|s:&str|s.as_bytes().get(1)==Some(&b':')||s.starts_with("//");
 if !(win(&a)&&win(&b)){return None;}
 if a.eq_ignore_ascii_case(&b){return Some(PathBuf::new());}
 let prefix=b+"/";if a.len()>=prefix.len()&&a.get(..prefix.len())?.eq_ignore_ascii_case(&prefix){Some(PathBuf::from(a.get(prefix.len()..)?))}else{None}
}
pub fn resolved(path:&Path)->PathBuf{let mut p=path.to_path_buf();if let Ok(moves)=MOVES.lock(){for(old,new)in moves.iter(){if let Some(rel)=move_suffix(&p,old){p=new.join(rel);}}}p}
fn equal(a:&Path,b:&Path)->Result<bool,String>{if fs::metadata(a).map_err(|e|e.to_string())?.len()!=fs::metadata(b).map_err(|e|e.to_string())?.len(){return Ok(false);}let mut a=fs::File::open(a).map_err(|e|e.to_string())?;let mut b=fs::File::open(b).map_err(|e|e.to_string())?;let mut x=[0u8;65536];let mut y=[0u8;65536];loop{let n=a.read(&mut x).map_err(|e|e.to_string())?;b.read_exact(&mut y[..n]).map_err(|e|e.to_string())?;if x[..n]!=y[..n]{return Ok(false);}if n==0{return Ok(true);}}}
fn copy_tree(old:&Path,new:&Path,depth:usize,files:&mut Vec<PathBuf>)->Result<(),String>{if depth>64{return Err("Save folder nesting is too deep".into());}for e in fs::read_dir(old).map_err(|e|e.to_string())?{let e=e.map_err(|e|e.to_string())?;let kind=e.file_type().map_err(|e|e.to_string())?;let target=new.join(e.file_name());if kind.is_symlink(){return Err("The save folder contains a symbolic link. Move that link out before relocating the folder.".into());}if kind.is_dir(){fs::create_dir(&target).map_err(|e|e.to_string())?;copy_tree(&e.path(),&target,depth+1,files)?;}else if kind.is_file(){fs::copy(e.path(),&target).map_err(|e|e.to_string())?;fs::OpenOptions::new().write(true).open(&target).and_then(|f|f.sync_all()).map_err(|e|e.to_string())?;if !equal(&e.path(),&target)?{return Err("A copied file failed verification. The original folder was kept.".into());}files.push(target);}else{return Err("A file cannot be copied safely".into());}}Ok(())}
fn rebase(v:&mut Value,old:&Path,new:&Path){match v{Value::Array(xs)=>for x in xs{rebase(x,old,new)},Value::Object(xs)=>for(key,x)in xs.iter_mut(){if ["path","filePath","projectFile","privateFile","openedFile","previewPath","subtitlerProjectFile"].contains(&key.as_str()){if let Some(s)=x.as_str(){if let Some(rel)=move_suffix(Path::new(s),old){*x=json!(new.join(rel));}}}else{rebase(x,old,new)}},_=>{}}}
pub fn move_folder(directory:&Path,parent:&Path)->Result<Value,String>{
 let requested=resolved(directory);let old=requested.canonicalize().map_err(|_|"The Subtitler save folder is missing. Locate it before moving it.".to_string())?;let home=std::env::var_os("HOME").or_else(||std::env::var_os("USERPROFILE")).map(PathBuf::from).map(|p|p.canonicalize().unwrap_or(p));
 if old.parent().is_none()||home.as_ref().is_some_and(|h|old==*h||["Desktop","Documents","Downloads","Pictures","Music","Videos","Library","AppData"].iter().any(|n|old==h.join(n)))||old.join("Studio Link").is_dir(){return Err("This is a general folder or Storyboard project, not a dedicated Subtitler folder. It was not moved.".into());}
 let parent=parent.canonicalize().map_err(|e|e.to_string())?;if !old.is_dir()||!parent.is_dir(){return Err("Choose a folder".into());}let name=old.file_name().ok_or("A filesystem root cannot be moved")?;let new=parent.join(name);if new==old{return Ok(json!({"old":old,"directory":new,"changed":false}));}if new.starts_with(&old)||old.starts_with(&new){return Err("Choose a location outside the current Subtitler folder".into());}if new.exists(){return Err("A folder with that name already exists. Choose another parent; no files were merged or replaced.".into());}
 let stage=parent.join(format!(".subtitler-moving-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_nanos()));fs::create_dir(&stage).map_err(|e|e.to_string())?;
 let result=(||{let mut files=Vec::new();copy_tree(&old,&stage,0,&mut files)?;let mut shared=std::collections::BTreeSet::new();for f in files.iter().filter(|p|p.extension().and_then(|s|s.to_str())==Some("subtitler")){let mut d=crate::audio_package::read(f)?.project;if let Some(dir)=d["studioLink"]["directory"].as_str(){shared.insert(PathBuf::from(dir).join("Studio Link"));}rebase(&mut d,&old,&new);crate::audio_package::write(f,&d)?;}
 let mut updates=Vec::new();for dir in shared{if !dir.is_dir(){continue;}let mut records=Vec::new();for folder in [&dir,&dir.join(".recordings")]{if !folder.is_dir(){continue;}for e in fs::read_dir(folder).map_err(|e|e.to_string())?{let e=e.map_err(|e|e.to_string())?;if e.file_type().map_err(|e|e.to_string())?.is_file(){records.push(e.path());}}}for p in records{let name=p.file_name().and_then(|s|s.to_str()).unwrap_or("");if name!="subtitler-files.json"&&!name.ends_with(".timing.json"){continue;}let bytes=fs::read(&p).map_err(|e|e.to_string())?;let mut v:Value=serde_json::from_slice(&bytes).map_err(|e|e.to_string())?;rebase(&mut v,&old,&new);let next=serde_json::to_vec_pretty(&v).map_err(|e|e.to_string())?;if bytes!=next{updates.push((p,bytes,next));}}}
 fs::rename(&stage,&new).map_err(|e|e.to_string())?;for(i,(path,_,bytes))in updates.iter().enumerate(){if let Err(e)=crate::project_files::atomic(path,bytes){let mut failed=false;for(p,previous,_)in &updates[..i]{if crate::project_files::atomic(p,previous).is_err(){failed=true;}}if !failed{let _=fs::remove_dir_all(&new);}return Err(format!("Connection update failed; original folder retained. {e}"));}}
 let mut moves=MOVES.lock().map_err(|e|e.to_string())?;moves.push((old.clone(),new.clone()));if requested!=old{moves.push((requested.clone(),new.clone()));}drop(moves);let warning=fs::remove_dir_all(&old).err().map(|e|format!("Files now save in the new location. Old folder could not be fully removed: {e}"));Ok(json!({"old":old,"directory":new,"changed":true,"warning":warning}))})();if result.is_err(){let _=fs::remove_dir_all(&stage);}result
}

#[cfg(test)]mod windows_path_tests{use super::*;
 #[test]fn verbatim_and_regular_windows_paths_share_a_binding(){assert_eq!(move_suffix(Path::new(r"c:\Users\J\Subtitler\Test.subtitler"),Path::new(r"\\?\C:\Users\J\Subtitler")),Some(PathBuf::from("Test.subtitler")));assert_eq!(move_suffix(Path::new(r"\\server\share\Subtitler\Test.subtitler"),Path::new(r"\\?\UNC\server\share\Subtitler")),Some(PathBuf::from("Test.subtitler")));assert!(move_suffix(Path::new(r"C:\Other\Test.subtitler"),Path::new(r"\\?\C:\Users\J\Subtitler")).is_none());}
}
